const recommendationCache=new Map();
function getRecommendations(){if(!selected.length)return[];const estimate=$('estimate').checked;const key=selected.join(',')+'|'+spatial+'|'+estimate;if(recommendationCache.has(key))return recommendationCache.get(key);const result=roster.map(a=>scoreAgainst(a,selected,spatial,estimate)).filter(r=>r.space>=0).sort((a,b)=>comparePicks(a,b,estimate));if(recommendationCache.size>=64)recommendationCache.delete(recommendationCache.keys().next().value);recommendationCache.set(key,result);return result}
function formName(s){return s==='basic-form'?'Standard':s==='prismana-form'?'Prismatic':s==='beach-form'?'Beach':'Nighttime'}
function pickCard(r,i){const a=r.a;let movement=spatial==='Unknown'?'Select the enemy’s Spatial state to check reach.':r.space>0?spatial==='Tunnel'?`Use ${r.m.name} to interrupt Tunnel. Pound tag: community reference.`:spatial==='Fly'?'Distance attack option against airborne enemies.':spatial==='Ranged'?'Use Tunnel to avoid ranged attacks while stamina lasts.':'Use its flying combat state to evade ground attacks.':'No confirmed Spatial advantage for this listed move.';return `<article class="pick"><div class="picktop"><div><span class="pickrank">${String(i+1).padStart(2,'0')}</span><strong>${a.name}</strong><span class="formtag">${formName(a.form)}</span></div><span class="role">${a.role}</span></div><div class="pickmeta">${a.elements.map(e=>`<span style="color:${colors[e]}">${types[e]}</span>`).join(' + ')}<span>Base ATK ${a.atk}</span></div><p class="pickmove">Use <strong>${r.m.name}</strong> · ${types[r.m.element]}${r.m.community?' · Pound tag (community)':''}</p><div class="factors">${selected.map((d,j)=>`<span class="factor ${cls(r.factors[j])}">vs ${types[d]} ×${fmt(r.factors[j])}</span>`).join('')}${$('estimate').checked?`<span class="factor">≈ ×${fmt(r.product)} combined</span>`:''}</div>${spatial==='Unknown'?'':`<p class="pickspatial">${movement}</p>`}<details class="pickDetails"><summary>Why this pick</summary><p class="hint">${a.note}</p><div class="pickbottom"><span class="hint">${r.incomingWeak} incoming weakness pair${r.incomingWeak===1?'':'s'} · enemy-element attacks only</span><a href="${a.source}" target="_blank" rel="noopener">Official form & skills</a></div></details></article>`}
function renderMoreRecommendations(){const rs=getRecommendations();$('morePicks').innerHTML=rs.slice(3).map((r,i)=>pickCard(r,i+3)).join('')}
function renderRecommendations(){const rs=getRecommendations();$('aniimoPicks').innerHTML=rs.length?rs.slice(0,3).map(pickCard).join(''):'<p class="hint">Select at least one enemy element to see recommended Aniimo.</p>';if($('moreCounterDetails').open)renderMoreRecommendations();else $('morePicks').innerHTML=''}


;
let selected=[0],prismatic=false,spatial='Unknown',namedEnemy=null;const $=id=>document.getElementById(id);
function render(){ $('elements').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',selected.includes(i)));$('elementSummary').textContent=selected.map(i=>types[i]).join(' + ')||'None';$('count').textContent=selected.length+' selected';$('normal').setAttribute('aria-pressed',namedEnemy?$('enemyForm').value==='basic-form':!prismatic);$('prism').setAttribute('aria-pressed',prismatic);$('formBadge').textContent=namedEnemy?(namedEnemy.forms.find(f=>f.key===$('enemyForm').value)?.label||'Standard').toUpperCase():prismatic?'PRISMATIC':'STANDARD';$('formHint').textContent=namedEnemy?'Elements loaded from the selected official form. Editing an element switches to a custom profile.':prismatic?'Select the actual form’s elements; no assumed Prismatic typing.':'Choose one or two elements shown in-game.';$('spatial').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',spatial===b.dataset.s));if(typeof syncEnemyProfile==='function')syncEnemyProfile();$('targetName').textContent=selected.length?(namedEnemy?namedEnemy.name+' · ':'')+selected.map(i=>types[i]).join(' + '):'Select enemy elements';const spatialNotes={Unknown:['Spatial state unknown','Select the active enemy movement or skill type to check reach.'],Tunnel:['Use a Pound skill against Tunnel','Ranged attacks cannot hit an actively tunnelling target. Pound skills can launch it out.'],Fly:['Bring a distance attack against Fly','Airborne enemies evade ground attacks and can take more damage in the air. Check the equipped skill’s reach.'],Ranged:['Tunnel can evade ranged attacks','This protection lasts while tunnelling and consumes stamina. Pound skills can interrupt it.'],Pound:['Flying can evade ground attacks','Use an actual flying combat state. Exploration flight alone does not establish a combat counter.']};$('spatialResult').innerHTML=`<strong>${spatialNotes[spatial][0]}</strong><p>${spatialNotes[spatial][1]}</p>`;const estimate=$('estimate').checked;$('modelHint').textContent=estimate?'Estimated product of all selected matchups. Multi-element stacking is not officially verified.':'Each column shows the move’s effectiveness against one enemy element.';
renderRecommendations();if(!selected.length){$('rankings').innerHTML='<p>Select at least one defending element to see counters.</p>';return}const rows=types.map((t,i)=>{const factors=selected.map(d=>matrix[i][d]);return{t,i,factors,product:factors.reduce((a,b)=>a*b,1),strong:factors.filter(v=>v>1).length,weak:factors.filter(v=>v<1).length}}).sort((a,b)=>estimate?b.product-a.product||a.i-b.i:b.strong-a.strong||a.weak-b.weak||a.i-b.i);$('rankings').innerHTML=rows.map(r=>`<div class="row"><div class="typeName" style="--c:${colors[r.i]}"><span aria-hidden="true">${glyphs[r.i]}</span>${r.t}</div><div class="factors">${selected.map((d,j)=>`<span class="factor ${cls(r.factors[j])}">${types[d]} ×${fmt(r.factors[j])}</span>`).join('')}</div><div class="assessment">${estimate?`<strong>≈ ×${fmt(r.product)}</strong>`:r.strong&&r.weak?'Mixed matchup':r.strong?'Advantage':r.weak?'Resisted':'Neutral'}</div></div>`).join('')}
$('elements').innerHTML=types.map((t,i)=>`<button class="element" style="--c:${colors[i]}" aria-pressed="false" data-i="${i}" title="${t}${i===3?' / Electric':i===5?' / Rock':i===7?' / Holy':''}"><span class="glyph" aria-hidden="true">${glyphs[i]}</span>${t}</button>`).join('');$('spatial').innerHTML=spatialTypes.map(t=>`<button aria-pressed="false" data-s="${t}">${t}</button>`).join('');
$('elements').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const i=Number(b.dataset.i);if(namedEnemy)clearNamedEnemy(false);if(selected.includes(i))selected=selected.filter(v=>v!==i);else if(prismatic||selected.length<2)selected.push(i);else{selected=[selected[1],i]}render()});$('spatial').addEventListener('click',e=>{const b=e.target.closest('button');if(b){spatial=b.dataset.s;render()}});$('normal').onclick=()=>{if(namedEnemy){applyNamedForm('basic-form');return}prismatic=false;selected=selected.slice(0,2);render()};$('prism').onclick=()=>{if(namedEnemy){applyNamedForm('prismana-form');return}prismatic=true;render()};$('estimate').onchange=render;$('reset').onclick=()=>{if(typeof clearNamedEnemy==='function')clearNamedEnemy(false);selected=[0];prismatic=false;spatial='Unknown';$('estimate').checked=false;render()};$('matrix').innerHTML='<table><caption class="hint">Move element × defending element</caption><thead><tr><th scope="col">ATK / DEF</th>'+types.map(t=>`<th scope="col">${t}</th>`).join('')+'</tr></thead><tbody>'+types.map((t,i)=>`<tr><th scope="row">${t}</th>${matrix[i].map(v=>`<td class="${cls(v)}">×${fmt(v)}</td>`).join('')}</tr>`).join('')+'</tbody></table>';


;
const nameNormalize=s=>s.trim().toLowerCase().replace(/[^a-z0-9]/g,'');
const dexById=new Map(aniimoDex.map(a=>[a.id,a]));
const nameIndex=aniimoDex.map(a=>({a,normalized:nameNormalize(a.name),keys:[a.name,...a.aliases,a.id].map(nameNormalize)}));
function searchDex(query){const q=nameNormalize(query);if(!q)return[];return nameIndex.filter(r=>r.keys.some(n=>n.includes(q))).sort((a,b)=>Number(b.normalized===q)-Number(a.normalized===q)||Number(b.normalized.startsWith(q))-Number(a.normalized.startsWith(q))||a.a.name.localeCompare(b.a.name)).map(r=>r.a)}


;
let visibleMatches=[],activeMatch=-1,profileKey='';
function hideMatches(){visibleMatches=[];activeMatch=-1;$('searchResults').innerHTML='';$('enemySearch').setAttribute('aria-expanded','false');$('enemySearch').removeAttribute('aria-activedescendant')}
function highlightMatch(){const buttons=$('searchResults').querySelectorAll('button');buttons.forEach((b,i)=>b.setAttribute('aria-selected',i===activeMatch));if(activeMatch>=0){$('enemySearch').setAttribute('aria-activedescendant',`match-${visibleMatches[activeMatch].id}`);buttons[activeMatch]?.scrollIntoView({block:'nearest'})}else $('enemySearch').removeAttribute('aria-activedescendant')}
function showNameMatches(){const query=$('enemySearch').value;if(!query.trim()){if(namedEnemy)clearNamedEnemy();else hideMatches();return}const matches=searchDex(query);activeMatch=-1;visibleMatches=matches.slice(0,8);$('enemySearch').removeAttribute('aria-activedescendant');$('enemySearch').setAttribute('aria-expanded',!!matches.length);if(!matches.length){$('searchResults').innerHTML='<p class="hint" role="status">No match in the checked index. Try another spelling or choose elements below.</p>';return}$('searchResults').innerHTML=visibleMatches.map(a=>`<button class="nameMatch" type="button" role="option" aria-selected="false" id="match-${a.id}" data-id="${a.id}"><strong>${a.name}</strong><span>${a.forms.length} form${a.forms.length===1?'':'s'}${a.forms.some(f=>f.key==='prismana-form')?' · ◇ Prismana':''} · #${a.id}</span></button>`).join('')+(matches.length>8?`<p class="hint">${matches.length} matches. Keep typing to narrow the list.</p>`:'')}
function selectEnemy(id){const a=dexById.get(id);if(!a)return;namedEnemy=a;$('enemySearch').value=a.name;hideMatches();$('enemyForm').innerHTML=a.forms.map(f=>`<option value="${f.key}">${f.label} · ${f.elements.map(e=>types[e]).join(" + ")}</option>`).join('');$('enemyForm').disabled=false;$('elementEditor').open=false;applyNamedForm(a.forms[0].key);$('enemyForm').focus({preventScroll:true})}
function applyNamedForm(key){if(!namedEnemy)return;const f=namedEnemy.forms.find(x=>x.key===key);if(!f)return;$('enemyForm').value=key;selected=[...f.elements];prismatic=key==='prismana-form';spatial='Unknown';render()}
function syncEnemyProfile(){if(!namedEnemy){$('normal').disabled=false;$('prism').disabled=false;return}const f=namedEnemy.forms.find(x=>x.key===$('enemyForm').value)||namedEnemy.forms[0];$('normal').disabled=!namedEnemy.forms.some(x=>x.key==='basic-form');$('prism').disabled=!namedEnemy.forms.some(x=>x.key==='prismana-form');const key=namedEnemy.id+'|'+f.key;if(profileKey===key)return;profileKey=key;$('enemyDetails').innerHTML=`<div class="factors">${f.elements.map(e=>`<span class="factor" style="color:${colors[e]}">${types[e]}</span>`).join('')}<a href="${f.source}" target="_blank" rel="noopener">Official form</a></div><p class="hint">${f.spatial==='Tunnel'?'Can tunnel. Choose Tunnel below only while underground.':f.spatial==='Fly'?'Has a flying combat skill. Choose Fly below only while airborne.':'Set the active Spatial state if known.'}</p>${namedEnemy.forms.length===1?`<p class="hint">${f.key==='prismana-form'?'Only Prismana is published for this entry.':'No Prismana form listed in the checked official Wiki.'}</p>`:''}`}
function clearNamedEnemy(rerender=true){namedEnemy=null;profileKey='';$('enemySearch').value='';hideMatches();$('enemyDetails').innerHTML='';$('enemyForm').innerHTML='<option>Select an Aniimo first</option>';$('enemyForm').disabled=true;$('normal').disabled=false;$('prism').disabled=false;$('elementEditor').open=true;if(rerender)render()}
$('enemySearch').addEventListener('input',showNameMatches);
$('enemySearch').addEventListener('keydown',e=>{if(e.key==='Escape'){hideMatches();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){if(!visibleMatches.length)showNameMatches();if(!visibleMatches.length)return;e.preventDefault();activeMatch=e.key==='ArrowDown'?(activeMatch+1)%visibleMatches.length:(activeMatch<=0?visibleMatches.length-1:activeMatch-1);highlightMatch();return}if(e.key==='Enter'){const matches=searchDex($('enemySearch').value);const chosen=activeMatch>=0?visibleMatches[activeMatch]:matches[0];if(chosen){e.preventDefault();selectEnemy(chosen.id)}}});
$('searchResults').addEventListener('click',e=>{const b=e.target.closest('button[data-id]');if(b)selectEnemy(b.dataset.id)});
$('enemyForm').addEventListener('change',()=>applyNamedForm($('enemyForm').value));
$('clearEnemy').onclick=()=>{clearNamedEnemy();$('enemySearch').focus()};
$('moreCounterDetails').addEventListener('toggle',()=>{if($('moreCounterDetails').open)renderMoreRecommendations()});
document.addEventListener('click',e=>{if(!e.target.closest('.enemylookup'))hideMatches()});
render();

